{"code": "import sys

# Stream-filter high-severity events from audit_stream.json to audit_high.json
with open('audit_stream.json', 'r') as fin, open('audit_high.json', 'w') as fout:
    for line_num, line in enumerate(fin):
        line = line.strip()
        if not line:
            continue
        try:
            # Parse JSON object
            import json
            obj = json.loads(line)
            # Check for 'severity' == 'high'
            if obj.get('severity') == 'high':
                fout.write(line + '\n')
        except json.JSONDecodeError:
            # Skip invalid lines, optionally log to stderr
            sys.stderr.write(f'Warning: Invalid JSON on line {line_num + 1}\n')
            continue"}
